#include <Windows.h>
#include <cstdint>
#include <iostream>
#include <stdexcept>
#include <string>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==4,"original x86 only");if(argc!=2)throw std::runtime_error("workspace library directory required");std::string dir=argv[1];if(!SetDllDirectoryA(dir.c_str()))throw std::runtime_error("DLL directory");HMODULE tier=LoadLibraryExA((dir+"\\tier0.dll").c_str(),nullptr,LOAD_WITH_ALTERED_SEARCH_PATH);if(!tier)throw std::runtime_error("tier0 load");HMODULE vstdlib=LoadLibraryExA((dir+"\\vstdlib.dll").c_str(),nullptr,LOAD_WITH_ALTERED_SEARCH_PATH);if(!vstdlib)throw std::runtime_error("vstdlib load");HMODULE fs=LoadLibraryExA((dir+"\\filesystem_stdio.dll").c_str(),nullptr,LOAD_WITH_ALTERED_SEARCH_PATH);if(!fs)throw std::runtime_error("filesystem load");using Factory=void*(__cdecl*)(const char*,int*);const auto factory=reinterpret_cast<Factory>(GetProcAddress(fs,"CreateInterface"));if(!factory)throw std::runtime_error("filesystem factory");int status=-1;void*object=factory("VFileSystem017",&status);if(!object||status)throw std::runtime_error("filesystem interface");const auto table=*reinterpret_cast<uintptr_t**>(object);for(unsigned i=0;i<70;++i)std::cout<<i<<" "<<std::hex<<table[i]-uintptr_t(fs)<<std::dec<<'\n';FreeLibrary(fs);FreeLibrary(vstdlib);FreeLibrary(tier);SetDllDirectoryA(nullptr);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
